add_filter( 'loop_shop_per_page', function() {
    return 24;
} );

// Related products: 4 in a row
add_filter( 'woocommerce_output_related_products_args', function ( $args ) {
    $args['posts_per_page'] = 4;
    $args['columns']        = 4;
    return $args;
} );


